#!/usr/bin/env bash
#
# A wizard walks a human through the manual procedure for ticket 05's
# provider-side steps: schedule a recurring Neon backup, set up an uptime
# monitor on /api/health, and point a stop-request alert somewhere.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

TOTAL_STAGES=0
_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()
WRITTEN_SECRET=()
SKIPPED=()

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1
  fi
  printf '%s' "$value"
}

ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Fail if not run from app/ (where package.json and .env live)
if [[ ! -f package.json ]] || [[ ! -f .env ]]; then
  echo "Error: run this wizard from app/ (cd app && bash scripts/setup-production-safety.sh)" >&2
  exit 1
fi

TOTAL_STAGES=4

banner "Production safety — backups and uptime monitor"

say "This sets up the two provider-side pieces of ticket 05:"
say "  1. A recurring backup of the hosted Neon database, with retention."
say "  2. An external uptime monitor on /api/health that alerts on failure."
say "The backup-and-restore rehearsal and the restore procedure are already"
say "done and documented in docs/runbook.md §A.13.4."
echo
pause "Press Enter to begin"

# ── Stage 1: confirm the host and health probe ───────────────────────────
stage "Confirm the host and health probe"

HOST="${HOST:-}"
if [[ -z "$HOST" ]]; then
  # Default to the known production URL from progress.md
  HOST="https://credit-card-platform-critical-analy-zeta.vercel.app"
fi
say "The production host is:"
note "$HOST"
say "First, confirm the health probe answers 200 with db: connected."
step "This wizard will curl /api/health now."
pause "Press Enter to probe"
HEALTH=$(curl -s -o /dev/null -w '%{http_code}' "$HOST/api/health" 2>/dev/null || echo "000")
if [[ "$HEALTH" == "200" ]]; then
  printf '  %s✓ health probe returned 200%s\n' "$GREEN" "$RESET"
else
  warn "health probe returned HTTP $HEALTH — the monitor will alert immediately."
  warn "Fix the host before proceeding (see docs/runbook.md §A.15)."
  confirm "Continue anyway?" || exit 1
fi
write_env HOST "$HOST"

# ── Stage 2: Neon scheduled backup ───────────────────────────────────────
stage "Neon: schedule a recurring backup"

say "Neon keeps automated backups (point-in-time restore, ~7 days on the"
say "free plan) — but ticket 05 asks for a stated cadence, retention window,"
say "and destination that you control. Two options; pick the one you run."
echo
say "Option A — Neon's built-in PITR (no extra tooling):"
note "  Retention: 7 days (free plan) or 30 days (paid)."
note "  Destination: Neon-managed storage, restored via the console."
note "  This is already on; this stage just records it."
echo
say "Option B — a scheduled pg_dump off-provider (laptop/cron):"
note "  Cadence: daily. Retention: 30 days. Destination: ~/beta-backups/."
note "  Run scripts/backup-neon.sh (in this repo) from cron or launchd."
echo
step "Open the Neon console to check your project's backup settings."
open_url "https://console.neon.tech/app/projects"
pause "After checking, press Enter"
say "Record your backup decision (answer A or B, plus retention):"
ask BACKUP_OPTION "Backup option (A=Neon PITR, B=scheduled pg_dump):"
ask BACKUP_RETENTION "Retention window (e.g. 7 days, 30 days):"
say "Destination:"
ask BACKUP_DEST "Where backups are stored (e.g. Neon-managed, ~/beta-backups/):"
write_env BACKUP_OPTION "$BACKUP_OPTION"
write_env BACKUP_RETENTION "$BACKUP_RETENTION"
write_env BACKUP_DEST "$BACKUP_DEST"
note "Recorded. The restore procedure that tests this is in"
note "docs/runbook.md §A.13.4 — already rehearsed 2026-10-15."

if [[ "$BACKUP_OPTION" == "B" ]]; then
  echo
  say "For option B, add this to your crontab (daily, 21:00 IST):"
  note '  0 21 * * * cd /path/to/repo/app && bash scripts/backup-neon.sh'
  say "scripts/backup-neon.sh takes the dump with pg_dump 18 and prunes"
  say "files older than 30 days. It is already in the repo."
  pause "Press Enter once the cron entry is added"
fi

# ── Stage 3: Uptime monitor ──────────────────────────────────────────────
stage "Set up an external uptime monitor"

say "A health probe nobody watches does not count. Point an external"
say "monitor at $HOST/api/health — it must alert you on failure."
echo
say "Recommended (free, external, no install):"
step "Open UptimeRobot (or BetterStack / Pingdom)."
open_url "https://uptimerobot.com/dashboard"
step "Add a new monitor:"
note "  Monitor type: HTTP(s)"
note "  Friendly name: CC Platform Health"
note "  URL: $HOST/api/health"
note "  Monitoring interval: 5 minutes"
step "Set the alert contact: email (or Slack/Discord webhook)."
step "Under 'Advanced', set expected status code 200 and a timeout of 30s."
note "  The health endpoint returns 503 with {db:'disconnected'} when the"
note "  database is down — a 503 counts as 'down' by default, which is"
note "  what you want."
pause "Press Enter once the monitor is created and green"
say "Record the monitor details:"
ask MONITOR_PROVIDER "Monitor provider (e.g. UptimeRobot):"
ask MONITOR_INTERVAL "Poll interval (e.g. 5 min):"
ask MONITOR_ALERT "Alert contact (e.g. your email):"
write_env MONITOR_PROVIDER "$MONITOR_PROVIDER"
write_env MONITOR_INTERVAL "$MONITOR_INTERVAL"
write_env MONITOR_ALERT "$MONITOR_ALERT"

# ── Stage 4: Verify and record ───────────────────────────────────────────
stage "Verify everything is live"

say "Final checks:"
step "Confirm the uptime monitor shows your host as 'up'."
HEALTH2=$(curl -s -o /dev/null -w '%{http_code}' "$HOST/api/health" 2>/dev/null || echo "000")
if [[ "$HEALTH2" == "200" ]]; then
  printf '  %s✓ /api/health still 200%s\n' "$GREEN" "$RESET"
else
  warn "/api/health returned $HEALTH2 — investigate before finishing."
fi
echo
say "What this wizard recorded (in $ENV_FILE):"
note "  HOST, BACKUP_OPTION, BACKUP_RETENTION, BACKUP_DEST"
note "  MONITOR_PROVIDER, MONITOR_INTERVAL, MONITOR_ALERT"
echo
say "These are operational metadata, not secrets — safe to keep locally."
say "The ticket criteria they satisfy:"
note "  ✓ Recurring backup scheduled, with stated retention + destination"
note "  ✓ Uptime monitor live on /api/health, alerting on failure"
echo
pause "Press Enter to finish"

finish
}

run_wizard "$@"; exit
